<?php $title='Add job'; require 'header.php'; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$vals=[];foreach(['title','department','location','work_mode','employment_type','description','requirements','salary'] as $f)$vals[$f]=trim($_POST[$f]??'');$s=db()->prepare("INSERT INTO jobs(title,department,location,work_mode,employment_type,description,requirements,salary) VALUES(?,?,?,?,?,?,?,?)");$s->bind_param('ssssssss',$vals['title'],$vals['department'],$vals['location'],$vals['work_mode'],$vals['employment_type'],$vals['description'],$vals['requirements'],$vals['salary']);$s->execute();header('Location:jobs.php');exit;}?>
